import{_ as t,o,c as d,a2 as s}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse(`{"title":"Windows setup from an Agent's shell","description":"","frontmatter":{},"headers":[],"relativePath":"records/windows-setup-episode.md","filePath":"records/windows-setup-episode.md"}`),n={name:"records/windows-setup-episode.md"};function a(r,e,i,c,h,l){return o(),d("div",null,[...e[0]||(e[0]=[s('<div class="warning custom-block"><p class="custom-block-title">Historical record</p><p>This page records what happened on a date, with its observed failures and limits. It is not a requirement for the current implementation. Current behaviour is in <a href="/Rho/docs/reference/status">Status</a>.</p></div><h1 id="windows-setup-from-an-agent-s-shell" tabindex="-1">Windows setup from an Agent&#39;s shell <a class="header-anchor" href="#windows-setup-from-an-agent-s-shell" aria-label="Permalink to &quot;Windows setup from an Agent&#39;s shell&quot;">​</a></h1><p>Updated 2026-11-07. The user&#39;s Agent installed Rho on Windows twice and reported what it met: <a href="https://github.com/YuLab-SMU/Rho/issues/112" target="_blank" rel="noreferrer">#112</a> (0.5.2 from source, 2026-11-02) and <a href="https://github.com/YuLab-SMU/Rho/issues/113" target="_blank" rel="noreferrer">#113</a> (0.5.4 from npm, following the setup page&#39;s Windows section, 2026-11-05). The user asked for both to be checked and resolved. This episode checks every item against <code>cd559cc0</code>, runs the Windows steps from an Agent&#39;s shell, and fixes what they exposed in Rho, the Plugins and Core.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ul><li>Windows 11 x64 (10.0.26200), Node 24.15.0, npm 11.12.1, Windows PowerShell 5.1.26100, R 4.5.1 and Chrome. Python is on <code>PATH</code> only as the Microsoft Store&#39;s aliases; Miniconda&#39;s 3.13.9 ran the Plugins suite.</li><li>The Agent is ZCode. Its shell is Git Bash with <code>C:\\Windows\\System32</code> ahead of <code>/usr/bin</code> in <code>PATH</code>, and with <code>LANG</code> and <code>LC_CTYPE</code> set to <code>C.UTF-8</code>.</li><li>A throwaway home (<code>USERPROFILE</code>, <code>HOMEDRIVE</code>, <code>HOMEPATH</code>) and npm prefix (<code>NPM_CONFIG_PREFIX</code>) under <code>work/windows-setup/</code>. Each PowerShell block was written to a <code>.ps1</code> file and run with <code>powershell -NoProfile -ExecutionPolicy Bypass -File</code>, as the page now says to do from Git Bash.</li><li>The person&#39;s own Rho 0.5.4 ran on <code>~/Rho/state</code> throughout and was left alone.</li></ul><h2 id="the-reports-on-current-main" tabindex="-1">The reports on current main <a class="header-anchor" href="#the-reports-on-current-main" aria-label="Permalink to &quot;The reports on current main&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>On <code>cd559cc0</code></th><th>Now</th></tr></thead><tbody><tr><td>#113.1 <code>uname -s</code> in Git Bash</td><td><code>MINGW64_NT-10.0-26200</code>, which step 1 did not name</td><td>Step 1 calls anything but <code>Darwin</code> or <code>Linux</code> Windows, and names it</td></tr><tr><td>#113.2 No look for an existing Rho</td><td>As reported</td><td>A PowerShell check of both state folders, and a listing of running services</td></tr><tr><td>#113.3 No log, ready line or <code>200</code></td><td>As reported</td><td>A background start with a log, the ready line and <code>200</code></td></tr><tr><td>#113.4 Stop only by Ctrl+Break</td><td>As reported; below, <code>Stop-Process</code> left a Host and no report</td><td><code>rho --stop</code></td></tr><tr><td>#113.5 Codex&#39;s <code>--agent-backend codex-acp</code></td><td>Missing</td><td>Named in step 4</td></tr><tr><td>#113.6 PowerShell and Git Bash</td><td><code>npm</code> failed in this shell: its <code>bash</code> was WSL&#39;s</td><td><code>npm.cmd</code>, <code>rho.cmd</code>, and <code>.ps1</code> files from Git Bash</td></tr><tr><td>#113.7 &quot;not yet run end to end on Windows&quot;</td><td>Still there</td><td>Replaced with what was run</td></tr><tr><td>#112.1 Install docs say unpublished</td><td>Already fixed: README and HEADLESS install from npm</td><td>—</td></tr><tr><td>#112.2 RELEASE names <code>rho-workspace-local-0.5.2.tgz</code></td><td>Still there</td><td>The packer&#39;s current name, with the old one explained</td></tr><tr><td>#112.3 Node 22 only</td><td>Already fixed: <code>&gt;=22.22.0 &lt;27</code>; 0.5.5 ran on Node 24.15.0 here</td><td>—</td></tr><tr><td>#112.4 Files the Agent used shown <code>missing</code></td><td>Already fixed in <code>5f0a701e</code>; no path in the example keeps the folder&#39;s name</td><td>—</td></tr><tr><td>#112.5 The Overview&#39;s timeline past its card</td><td>Reproduced</td><td>Fixed</td></tr><tr><td>#112.6 &quot;R 4.5.2 on this machine&quot;</td><td>Reproduced</td><td>Notebook 0.5.6</td></tr><tr><td>#112.7a Core&#39;s build only in <code>ci.yml</code></td><td>As reported</td><td>HEADLESS gives it</td></tr><tr><td>#112.7b A CRLF checkout changes Core</td><td>Reproduced with a build</td><td>Core <code>8ef933a</code></td></tr><tr><td>#112.7c Plugins&#39; <code>npm ci</code> took 14.5 minutes</td><td>Not rerun</td><td>HEADLESS says why</td></tr><tr><td>#112.7d A local Core is not CI&#39;s and names the builder</td><td>Reproduced: 78 paths</td><td>HEADLESS says so; not changed</td></tr><tr><td>#112.8 <code>npm</code> in Git Bash</td><td>Reproduced</td><td>As #113.6</td></tr></tbody></table><h2 id="baseline-0-5-5-from-npm" tabindex="-1">Baseline: 0.5.5 from npm <a class="header-anchor" href="#baseline-0-5-5-from-npm" aria-label="Permalink to &quot;Baseline: 0.5.5 from npm&quot;">​</a></h2><p><code>npm install -g @rho-workspace/rho</code> into the throwaway prefix took 188 s.</p><p><strong>A background start that holds the Agent&#39;s command.</strong> <code>Start-Process rho.cmd -WindowStyle Hidden -RedirectStandardOutput … -RedirectStandardError …</code> started Rho, and its ready line was in the log within 2 s. The Agent&#39;s command returned only 4 min 25 s later, when Rho was stopped: PowerShell starts a redirected program with handle inheritance, so Rho&#39;s <code>cmd.exe</code> and <code>node</code> held the Agent&#39;s output pipe. <code>Start-Process cmd.exe</code> without PowerShell&#39;s redirection, with <code>cmd</code> writing <code>&gt; rho.log 2&gt;&amp;1</code>, returned in 1.7 s. Rho kept running after the command ended and answered <code>200</code>.</p><p><strong>An old log read as this start&#39;s.</strong> With the previous run&#39;s log in place, the wait for the ready line passed at once (&quot;waited 0 s&quot;): <code>Start-Process</code> returns before <code>cmd</code> truncates the file.</p><p><strong><code>Stop-Process</code>, the only stop an Agent had.</strong> With a Notebook R session and a managed Core Host running, <code>Stop-Process</code> on Rho&#39;s <code>node</code> ended <code>node</code>, its <code>cmd.exe</code> and the R session (Node&#39;s job), but not the Host, and the log had no <code>{&quot;shutdown&quot;:…}</code> line. Touching the project&#39;s <code>.rho/host.stop</code> stopped the Host.</p><p><strong>Commands that PowerShell changes.</strong> <code>npm</code> and <code>rho</code> in PowerShell are <code>npm.ps1</code> and <code>rho.ps1</code>; with the <code>Restricted</code> execution policy, Windows&#39; default, <code>npm -v</code> was refused. Windows PowerShell 5.1 dropped the inner double quotes of step 7&#39;s R check, and R stopped with <code>unexpected symbol</code>; the same checks with single quotes inside R printed <code>TRUE</code> and <code>missing: DESeq2</code>. The skill&#39;s eight files downloaded with <code>Invoke-WebRequest</code>, with and without <code>-UseBasicParsing</code>.</p><p><strong>A locale Windows does not have.</strong> Found while running the Plugins suite from this shell: R on Windows takes <code>LC_ALL</code>, <code>LC_CTYPE</code>, <code>LC_COLLATE</code>, <code>LC_TIME</code> and <code>LC_MONETARY</code> from the environment, and Windows has no <code>C.UTF-8</code>. Given this shell&#39;s <code>LC_CTYPE</code>, R warned at startup, ran in the C locale and printed <code>3 × 2 中文</code> as <code>3 &lt;U+00D7&gt; 2 &lt;U+4E2D&gt;&lt;U+6587&gt;</code>. 0.5.5 started from this shell refused a Notebook cell whose code held that text: its runner could not read its own request (<code>lexical error: invalid character inside string</code>). A managed run printed the escapes, and the kernel tests left an R session that kept their file from exiting. <code>LANG=C.UTF-8</code>, <code>LANG=zh_CN.UTF-8</code> and <code>LC_CTYPE=en_US.UTF-8</code> were fine.</p><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><p><strong><code>rho --stop [--state-dir DIR]</code></strong> (Rho). The launcher looks for <code>service.stop</code> in its state folder every half second and, when it finds one, removes it and stops as on Ctrl+C. <code>--stop</code> leaves the file only while the state&#39;s writer lock is held, then waits until the lock is free and the process <code>connection.json</code> now names has ended, and prints <code>{&quot;stopped&quot;:{&quot;state&quot;:…}}</code>. The first version printed that once the lock was free, while the launcher was still writing its last line, and removing the log failed with &quot;Device or resource busy&quot;; with the wait for the process, the log was removed at once. A start removes a request no service took. Against 0.5.5, which never takes it, <code>--stop</code> said so after 10 s and removed its request. <code>launcher-stop.test.mjs</code> covers a request left before a start, the stop with a Host when Core is selected, and both refusals.</p><p><strong>The setup page and skill</strong> (Rho). Step 1 names Git Bash&#39;s <code>uname</code>. The Windows section mirrors steps 1 to 8: the existing-Rho check, <code>npm.cmd</code>, the background start through <code>cmd.exe</code> with the old log removed and <code>LC_ALL</code> and <code>LC_CTYPE</code> left out, <code>200</code> in a separate command, Codex&#39;s backend, the skill with a line per failed file, the R checks with single quotes, and <code>rho.cmd --stop</code>, with what <code>Stop-Process</code> leaves for a version without it. Step 8 elsewhere gives <code>rho --stop</code> before <code>pkill</code>.</p><p><strong>The Overview&#39;s timeline</strong> (Rho, <code>web/graph.tsx</code>). Each pause between stretches of work took a fixed 44 px. A fresh copy of the example has 21 stretches, so 880 px of pauses in a 329 px track: the plot was drawn 980 px wide, the main area scrolled from 979 to 1,233 px, and labels piled up. Pauses now take at most half the track, a pause is labelled only when it has room, and a tick label nearer the one before it than 60 px, or one that would start past the end, is left out. The Graph page&#39;s timeline, which had the same arithmetic, shows no pause labels for this project now.</p><p><strong>&quot;On this machine&quot;</strong> (Plugins <code>dd7ac26</code>, Notebook 0.5.6). The Overview said it of every session whose place was not a server. An ended session may come with a copied project, as the example&#39;s do, so only a live one says it now; the Notebook view never did.</p><p><strong>Locales</strong> (Plugins <code>edf7dfa</code>, Rho <code>src/bridge.ts</code>). A local Notebook session and a Core Host on Windows now start without those five categories&#39; POSIX UTF-8 values, so R takes the system&#39;s own locale, UTF-8 there. A Windows test in each owner fails without the change.</p><p><strong>Core&#39;s compiled-in documents</strong> (Core <code>8ef933a</code>, <a href="https://github.com/YuLab-SMU/Rho-core/blob/main/docs/work/CORE-20261107-01.md" target="_blank" rel="noreferrer">CORE-20261107-01</a>). A fresh clone under Git for Windows&#39; default <code>core.autocrlf=true</code> checked <code>docs/ACTIVITY.md</code> and <code>docs/MANAGED-RUN.md</code> out with 344 CR bytes, and a Core built from it embedded them with CRLF where CI&#39;s has LF. Those two files are now <code>text eol=lf</code>; a fresh clone builds them in with LF. The packer now records them among Core&#39;s build inputs. Rho still selects Core <code>8bed8ef</code>, so HEADLESS says to clone with <code>core.autocrlf false</code>, as CI does.</p><p><strong>Building from source</strong> (HEADLESS, RELEASE). HEADLESS gives CI&#39;s Core build, the Windows Core in the packer&#39;s example, what a local Core embeds (78 paths under the builder&#39;s user folder; CI&#39;s Core names <code>runneradmin</code> as often), <code>--core-composition</code> for reusing the accepted Cores, and the Agent adapters&#39; optional clients behind #112&#39;s 14.5-minute <code>npm ci</code>. RELEASE names the tarball the packer writes now.</p><h2 id="the-rerun" tabindex="-1">The rerun <a class="header-anchor" href="#the-rerun" aria-label="Permalink to &quot;The rerun&quot;">​</a></h2><p>The candidate was packed from Plugins <code>edf7dfa</code> and an earlier, unpublished state of these Rho commits (application commit <code>8e39ef1f</code>, on <code>cd559cc0</code>), reusing the published 0.5.5&#39;s <code>win32-x64</code> Core through <code>--core-composition</code>: 125 s, and <code>rho-workspace-rho-0.5.6.tgz</code> of 19,270,055 bytes and 3,163 files. Since then one comment in <code>web/graph.tsx</code> was corrected, and the commits were placed after three that arrived upstream meanwhile (conversation names and records). The tarball took the registry&#39;s place in step 3, installed with <code>npm.cmd install -g</code> into a new throwaway prefix and home. The PowerShell blocks were taken from <code>SETUP.md</code> as written, and step 4 was run again after its locale line was added; the published page&#39;s blocks are those, byte for byte.</p><table tabindex="0"><thead><tr><th>Step</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td><code>uname -s</code> printed <code>MINGW64_NT-10.0-26200</code>: Windows</td></tr><tr><td>2</td><td>Nothing installed and no state folder; the listing showed only the person&#39;s 0.5.4</td></tr><tr><td>3</td><td>23 s; <code>npm.cmd ls -g</code> named the version and <code>rho.cmd --help</code> listed <code>--stop</code></td></tr><tr><td>4</td><td>The command returned in 2.7 s with the ready line; a separate check printed <code>200</code>; step 2 then reported the state answering <code>200</code></td></tr><tr><td>5</td><td>Eight files, <code>name: rho</code></td></tr><tr><td>6</td><td>One JSON line; its stdio MCP server listed the four tools, and <code>rho_index</code> named the granted project</td></tr><tr><td>7</td><td><code>TRUE</code> and <code>missing: DESeq2</code>, each after R&#39;s warning about this shell&#39;s <code>LC_CTYPE</code>, which the page now explains</td></tr><tr><td>Notebook</td><td>A cell printing <code>3 × 2 中文</code> printed it, on the candidate and on 0.5.5 started by the final step 4</td></tr><tr><td>8</td><td><code>rho.cmd --stop</code> in 1.6 s with a live Notebook session; nothing left running; the log ended with <code>{&quot;shutdown&quot;:[]}</code>; a start at once returned in 1.9 s and answered <code>200</code>; the next stop took 0.7 s</td></tr></tbody></table><p>In Chrome at 1280 × 720 the candidate&#39;s Overview no longer scrolls sideways (979 of 979 px), and its Notebook section reads &quot;R 4.5.1 on this machine&quot; for the live session and &quot;R 4.5.2&quot; for the example&#39;s ended ones. The timeline was also measured at 1024, 1440 and 390 px, and the Graph page&#39;s at 1440, each without anything outside its card.</p><h2 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Windows result</th></tr></thead><tbody><tr><td>Rho <code>npm test</code>, Core selected</td><td>304 of 319, 15 skipped, none failed</td></tr><tr><td><code>launcher-stop.test.mjs</code>, <code>windows-locale.test.mjs</code></td><td>Pass with and without a Core; the locale test fails without its change</td></tr><tr><td>Plugins <code>npm test</code>, Miniconda&#39;s Python first on <code>PATH</code></td><td>180 of 190, 8 skipped, 2 failed, both from before this work: the interpreter test names <code>.venv/bin/nothing</code>, which on Windows is refused as outside the project because <code>bin</code> does not exist, and the presentation test expects <code>agent.sessions.list</code> to have no title, which Plugins <code>434d9a3</code> gave it</td></tr><tr><td>Plugins kernel locale test</td><td>Fails without the change</td></tr></tbody></table><p>Before the locale change, the Plugins suite run from this shell stopped making progress in <code>kernel.test.mjs</code> until it was ended; without Python on <code>PATH</code> ten kernel tests failed with exit 9009.</p><p><a href="https://github.com/YuLab-SMU/Rho/actions/runs/42370939615" target="_blank" rel="noreferrer">CI run 42370939615</a> on <code>ada6de57</code>, with Plugins <code>edf7dfa</code>, passed every job. The suite ran 316 of 319 tests on macOS arm64 and Linux x64 (3 skipped) and 302 of 319 on Windows x64 (17 skipped), none failing; <code>rho --stop</code> passed on all three and the locale test on Windows. The candidate installed offline on macOS arm64, Linux arm64, Linux x64 with Node 22, 24 and 26, and Windows x64.</p><h2 id="not-done" tabindex="-1">Not done <a class="header-anchor" href="#not-done" aria-label="Permalink to &quot;Not done&quot;">​</a></h2><ul><li>The <code>--stop</code>, timeline, Notebook and locale changes reach people with the next npm release.</li><li>The setup page and skill on the site are the earlier ones until they are deployed.</li><li><code>--open</code> was given; whether a tab opened was not seen from the Agent&#39;s side.</li><li>Codex is not installed here; Claude Code and Codex did not hold a conversation in this Rho.</li><li>Agents whose tools end the processes they start were not tried; the page&#39;s fallback is a window the person keeps open.</li><li>Windows on arm64, PowerShell 7, the two Plugins test failures above, and <code>--remap-path-prefix</code> for local Cores, which would change every platform&#39;s Core.</li></ul><p>Work ran from 18:13 to 20:00 (+08:00) on 2026-11-07, before the commits were published.</p>',33)])])}const w=t(n,[["render",a]]);export{u as __pageData,w as default};
